// AMBIGUOUS_CONTENT_GUARDS_FOLLOWUP — guard #2: ambiguous / empty / pronoun-only memory.
function asciiFold(s) {
  return String(s).toLowerCase()
    .replace(/[\u0219\u015F]/g, 's')
    .replace(/[\u021B\u0163]/g, 't')
    .replace(/\u0103/g, 'a')
    .replace(/\u00E2/g, 'a')
    .replace(/\u00EE/g, 'i')
    .replace(/\u00E3/g, 'a');
}
